import re

def retrieve(query, documents, k=3):
    def terms(text):
        return set(re.findall(r"[\w]+", text.lower()))
    q = terms(query)
    scored = []
    for doc_id, text in documents.items():
        d = terms(text)
        score = len(q & d) / max(1, len(q | d))
        if score:
            scored.append((score, doc_id))
    return sorted(scored, key=lambda x: (-x[0], x[1]))[:k]

assert retrieve("vector search", {"a":"vector search index", "b":"weather"})[0][1] == "a"

def execute_plan(calls, max_steps=3):
    tools = {"add": lambda a,b: a+b}
    if len(calls) > max_steps:
        raise ValueError("step budget exhausted")
    results = []
    for call in calls:
        if call["tool"] not in tools:
            raise ValueError("tool not allowed")
        args = call["args"]
        if set(args) != {"a", "b"} or any(type(x) not in (int,float) for x in args.values()):
            raise ValueError("invalid arguments")
        results.append(tools[call["tool"]](**args))
    return results

assert execute_plan([{"tool":"add","args":{"a":2,"b":3}}]) == [5]
